const allTopics = [];

// High-CPM tech sub-niches (AI, SaaS, business, security, fintech) earn 2-4x more
// ad revenue than generic tech. Boost topics whose title matches these keywords so
// the channel naturally drifts toward the more monetizable end of tech.
const HIGH_CPM = ['ai', 'artificial intelligence', 'gpt', 'llm', 'openai', 'anthropic', 'machine learning', 'saas', 'startup', 'funding', 'raises', 'ipo', 'acquisition', 'enterprise', 'cloud', 'aws', 'azure', 'security', 'cybersecurity', 'breach', 'privacy', 'fintech', 'crypto', 'business', 'revenue', 'automation', 'api', 'developer tools', 'productivity'];
function cpmBoost(title) {
  const t = (title || '').toLowerCase();
  for (const kw of HIGH_CPM) {
    if (t.includes(kw)) return 2.5;
  }
  return 1;
}

for (const item of items) {
  const d = item.json;

  // Hacker News (via Algolia) - one item, hits array
  if (d.hits) {
    for (const hit of d.hits) {
      allTopics.push({
        title: hit.title,
        score: ((hit.points || 0) + ((hit.num_comments || 0) * 5)) * cpmBoost(hit.title),
        source: 'hackernews'
      });
    }
  }

  // YouTube trending - one item, items array
  if (d.items) {
    for (const video of d.items) {
      const views = parseInt(video.statistics?.viewCount || 0);
      allTopics.push({
        title: video.snippet.title,
        score: (views / 1000) * cpmBoost(video.snippet.title),
        source: 'youtube'
      });
    }
  }

  // Dev.to trending articles - HTTP node splits the JSON array into one item per article
  if (d.title && d.positive_reactions_count !== undefined) {
    allTopics.push({
      title: d.title,
      score: ((d.positive_reactions_count || 0) + ((d.comments_count || 0) * 5)) * cpmBoost(d.title),
      source: 'devto'
    });
  }
}

if (allTopics.length === 0) throw new Error('No topics found from any source');

allTopics.sort((a, b) => b.score - a.score);
const best = allTopics[0];

// date/used are plain values here so Log Topic to Sheets can auto-map them.
// (Sheets resource-mapper expressions for date/topic were appending blank cells.)
return [{ json: {
  topic: best.title,
  score: best.score,
  source: best.source,
  date: new Date().toISOString().split('T')[0],
  used: 'TRUE'
} }];

const json = items[0].json;

const raw =
  json.choices?.[0]?.message?.content ||
  json.body?.choices?.[0]?.message?.content ||
  json.response?.choices?.[0]?.message?.content;

if (!raw) {
  throw new Error('Unexpected response shape: ' + JSON.stringify(json, null, 2));
}

// Model may wrap its JSON in markdown fences despite instructions - strip them defensively
const cleaned = raw.trim().replace(/^```(?:json)?\n?/, '').replace(/```$/, '');

// Small/fast models are unreliable at emitting strictly valid JSON for long text
// fields. Observed failure modes so far: (1) raw unescaped newlines inside a string
// value, (2) the response getting cut off before the closing brace (token limit),
// (3) the 'script' value split into several adjacent quoted strings instead of one
// continuous string, (4) the model leaking a raw chat-template token (e.g.
// 'assistant<|end_header_id|>') mid-object and then restarting that object from
// scratch further on, (5) the model omitting an object's closing '}' right before
// the array/object around it closes (e.g. the last item in sections[]), (6) the
// model using unescaped scare quotes for emphasis inside a string value, which
// prematurely terminates that string. Repair each using JSON.parse's own error
// position rather than guessing the shape up front.
function autoCloseTruncated(s) {
  let inString = false;
  let escapeNext = false;
  const stack = [];
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (escapeNext) { escapeNext = false; continue; }
    if (ch === '\\') { escapeNext = true; continue; }
    if (ch === '"') { inString = !inString; continue; }
    if (inString) continue;
    if (ch === '{' || ch === '[') stack.push(ch);
    else if (ch === '}' || ch === ']') stack.pop();
  }
  let suffix = '';
  if (inString) suffix += '"';
  for (let i = stack.length - 1; i >= 0; i--) {
    suffix += stack[i] === '{' ? '}' : ']';
  }
  return s + suffix;
}

// Find the position of the '{' that starts the innermost object still open at `pos`.
function findEnclosingBraceStart(s, pos) {
  let inString = false;
  let escapeNext = false;
  const stack = [];
  for (let i = 0; i < pos && i < s.length; i++) {
    const ch = s[i];
    if (escapeNext) { escapeNext = false; continue; }
    if (ch === '\\') { escapeNext = true; continue; }
    if (ch === '"') { inString = !inString; continue; }
    if (inString) continue;
    if (ch === '{') stack.push(i);
    else if (ch === '}') stack.pop();
  }
  return stack.length ? stack[stack.length - 1] : null;
}

function repairAndParse(text) {
  let s = text;
  for (let attempts = 0; attempts < 1000; attempts++) {
    try {
      return JSON.parse(s);
    } catch (e) {
      const m = /position (\d+)/.exec(e.message);
      const pos = m ? parseInt(m[1], 10) : null;

      // Truncated - the parser ran off the end of the string. Close it out.
      if (pos !== null && pos >= s.length) {
        const closedUp = autoCloseTruncated(s);
        if (closedUp !== s) { s = closedUp; continue; }
        throw e;
      }
      // Raw control character (unescaped newline/tab/CR) inside a string value.
      if (pos !== null && /bad control character/i.test(e.message)) {
        const ch = s[pos];
        const escapeMap = { '\n': '\\n', '\r': '\\r', '\t': '\\t' };
        const replacement = escapeMap[ch];
        if (replacement === undefined) throw e;
        s = s.slice(0, pos) + replacement + s.slice(pos + 1);
        continue;
      }
      // Two adjacent quoted strings where a comma/brace was expected - the model
      // split one string value into several. Merge them into a single string.
      // Or: the model omitted the closing '}' for an object right before the
      // enclosing array/object closes (e.g. the last item in sections[]) - insert
      // the missing '}' and retry. Or: an unescaped scare-quote inside the string
      // prematurely closed it - escape that quote and retry.
      if (pos !== null && /Expected ',' or '}' after property value/i.test(e.message)) {
        if (s[pos] === '"') {
          let i = pos - 1;
          while (i >= 0 && /\s/.test(s[i])) i--;
          if (s[i] === '"') {
            s = s.slice(0, i) + ' ' + s.slice(pos + 1);
            continue;
          }
        } else if (s[pos] === ']' || s[pos] === '}') {
          s = s.slice(0, pos) + '}' + s.slice(pos);
          continue;
        } else {
          let i = pos - 1;
          while (i >= 0 && /\s/.test(s[i])) i--;
          if (s[i] === '"') {
            s = s.slice(0, i) + '\\' + s.slice(i);
            continue;
          }
        }
      }
      // Fallback: the model emitted garbage (leaked special token, glitch, etc.)
      // partway through an object and then restarted that same object from
      // scratch further on. Find the object currently open at the failure point
      // and the next '{' after it - if one exists, drop the broken partial
      // object and keep the restarted (complete) one.
      if (pos !== null) {
        const brokenStart = findEnclosingBraceStart(s, pos);
        const restartPos = s.indexOf('{', pos);
        if (brokenStart !== null && restartPos !== -1 && restartPos > pos) {
          s = s.slice(0, brokenStart) + s.slice(restartPos);
          continue;
        }
      }
      throw e;
    }
  }
  throw new Error('Could not repair JSON after 1000 attempts');
}

let parsed;
try {
  parsed = repairAndParse(cleaned);
} catch (e) {
  throw new Error('Model did not return valid JSON. Raw response: ' + raw);
}

if (!parsed.title || !parsed.script) {
  throw new Error('Parsed JSON missing required title/script fields: ' + JSON.stringify(parsed));
}

return [{ json: { raw, ...parsed } }];

const s = items[0].json;

if (!s.script) {
  throw new Error('Missing script text. Response JSON: ' + JSON.stringify(s, null, 2));
}

return [{
  json: {
    ...s,
    fullScript: s.script,
  }
}];

const script = $('Build Full Script').item.json;

return [{
  json: {
    ...script,
    audioLocalPath: $env.YT_TMP_DIR + '/voice.mp3'
  }
}];

const script = items[0].json;
const sections = script.sections || [];
const headings = sections.length > 0 ? sections.map(s => s.heading) : [script.title];

// Full headings make poor stock-footage search queries - keep it to a few significant words instead.
const stopWords = new Set(['the','a','an','and','or','but','of','in','on','at','to','for','with','is','are','why','how','what']);
const keywords = headings.map(h => {
  const words = h.replace(/[^a-zA-Z0-9\s]/g, '').split(/\s+/).filter(w => w && !stopWords.has(w.toLowerCase()));
  return words.slice(0, 3).join(' ') || h;
});

return keywords.map(k => ({ json: { currentItem: k } }));

const videos = items[0].json.videos;
if (!videos || videos.length === 0) throw new Error('No Pexels clips found');

const clip = videos.find(v => v.video_files.some(f => f.quality === 'hd')) || videos[0];
const file = clip.video_files.find(f => f.quality === 'hd') || clip.video_files[0];

return [{ json: { clipUrl: file.link, duration: clip.duration } }];

const clips = items.map((item, i) => ({
  localPath: item.json.fileName,
  index: i
}));

const script = $('Prepare Voiceover Data').item.json;

return [{ json: { ...script, clips, totalClips: clips.length } }];

const d = items[0].json;

const manifest = {
  clips: d.clips.map(c => c.localPath),
  audio: d.audioLocalPath,
  title: d.title || '',
  output: $env.YT_TMP_DIR + '/final_video.mp4',
  clipLength: 8
};

return [{ json: { ...d, manifestJson: JSON.stringify(manifest), outputPath: manifest.output } }];

// Thumbnail is now generated LOCALLY by scripts/generate_thumbnail.py (offline, brand
// controlled, per-title variation) instead of the remote Render service. Expose the
// title so the next node can write it to a text file the script reads.
return [{ json: { thumbTitle: $('Attach Video Metadata').item.json.title || 'Nexiora' } }];

const script = $('Attach Video Metadata').item.json;
const sections = script.sections || [];
const avgSectionDuration = 120;

const chapters = [
  '0:00 Introduction',
  ...sections.map((sec, i) => {
    const totalSeconds = 30 + (i * avgSectionDuration);
    const mins = Math.floor(totalSeconds / 60);
    const secs = totalSeconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')} ${sec.heading}`;
  })
];

const branding = '\n\n---\nSubscribe to Nexiora for daily tech & AI news: https://youtube.com/@TheNexiora\n\n#Nexiora #TechNews #AI';
const description = script.description + '\n\n' + chapters.join('\n') + branding;

return [{ json: { ...script, description, chapters }, binary: $('Attach Video Metadata').item.binary }];

// Publish tomorrow at 5:00 PM US Eastern (America/New_York), DST-safe.
const publishDate = new Date();
publishDate.setUTCDate(publishDate.getUTCDate() + 1);

function nyOffset(date) {
  const tz = new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', timeZoneName: 'short' })
    .formatToParts(date).find(p => p.type === 'timeZoneName').value;
  return tz === 'EDT' ? -4 : -5;
}

publishDate.setUTCHours(17 - nyOffset(publishDate), 0, 0, 0);

return [{
  json: {
    ...items[0].json,
    publishAt: publishDate.toISOString()
  },
  binary: $('Attach Video Metadata').item.binary
}];

// Carry the uploaded video id forward and re-attach the thumbnail image binary
// (produced locally by 'Read Thumbnail File', property 'thumbnail') so the next node can upload it.
return [{
  json: items[0].json,
  binary: $('Read Thumbnail File').item.binary
}];

